-- SP-NO7 — Notes de la v1 (Codex DD3.5) chargées dans des tables de transit.
--
-- Source : export phpMyAdmin « Export-Notes-dd3.5.sql » (57 notes, 95 blocs à DD, 22 liens de mots-clés).
-- Les INSERT de l'export sont repris à l'identique ; seules les tables sont renommées (dd_v1_*), et
-- leurs colonnes gardent les noms de la v1. Rien n'est versé dans dd_notes ici : l'import se lance
-- depuis l'écran admin/import-notes-v1.php, qui choisit la campagne cible, les catégories et les
-- compétences (D-NO14). dd_v1_notes.no_importe_no_id retient la note créée : un import relancé
-- ne reprend que les notes non encore importées.
-- Les colonnes no_texte_basique … no_texte_expert sont des copies anciennes et partielles des
-- blocs : l'import les ignore. Tables à supprimer après l'import en production (SP-NO8).
-- Pas de DELIMITER.

CREATE TABLE dd_v1_notes (
  no_id                  MEDIUMINT NOT NULL,
  no_tyno_id             INT NOT NULL COMMENT 'Type v1 (1 à 8), libellés absents de l\'export',
  no_nom                 VARCHAR(100) NOT NULL,
  no_texte_basique       LONGTEXT NULL,
  no_texte_intermediaire LONGTEXT NULL,
  no_texte_avance        LONGTEXT NULL,
  no_texte_expert        LONGTEXT NULL,
  no_date                DATETIME NOT NULL,
  no_j_id                MEDIUMINT NOT NULL,
  no_cumulatif           INT NOT NULL,
  no_importe_no_id       INT UNSIGNED NULL COMMENT '-> dd_notes créée par l\'import',
  PRIMARY KEY (no_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE dd_v1_notes_contenus (
  noc_id    MEDIUMINT NOT NULL,
  noc_no_id MEDIUMINT NOT NULL,
  noc_dd    TINYINT NOT NULL DEFAULT 10,
  noc_texte MEDIUMTEXT NOT NULL,
  PRIMARY KEY (noc_id),
  KEY idx_v1noc_no (noc_no_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE dd_v1_notes_tags (
  notag_id     INT UNSIGNED NOT NULL,
  notag_no_id  INT UNSIGNED NOT NULL,
  notag_tag_id INT UNSIGNED NOT NULL COMMENT 'Mot-clé v1 (1 à 9), libellés absents de l\'export',
  PRIMARY KEY (notag_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;





















